            <link rel="stylesheet" href="/css/style.css">

            </head>

            <body>

            <div class="page">

                <!-- HEADER -->

                    <header>

                            <div>
                                        <h1>♛ Task Manager</h1>

                                                    <p class="subtitle">
                                                                    Better plans. Bigger dreams.
                                                                                </p>
                                                                                        </div>

                                                                                                <div class="date">
                                                                                                            📅 {{ now()->format('F d, Y') }}
                                                                                                                        <br>
                                                                                                                                    {{ now()->format('g:i A') }}
                                                                                                                                            </div>

                                                                                                                                                </header>


                                                                                                                                                    <!-- ADD TASK -->

                                                                                                                                                        <div class="box add-box">

                                                                                                                                                                <h2>+ Add Task</h2>

                                                                                                                                                                        <form action="/tasks" method="POST">

                                                                                                                                                                                    @csrf

                                                                                                                                                                                                <div class="form">

                                                                                                                                                                                                                <input
                                                                                                                                                                                                                                    type="text"
                                                                                                                                                                                                                                                        name="task_name"
