                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <select name="status">

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <option value="Pending">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Pending
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </option>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <option value="Ongoing">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Ongoing
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </option>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <option value="Completed">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Completed
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </option>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </select>

